    h = int(lines[0].split()[0])
    w = int(lines[0].split()[1])
    grid = [list(line) for line in lines[1:]]
    return h, w, grid

def bfs(grid, h, w, x, y, visited):
    queue = deque([(x, y)])
    visited[x][y] = True
    component = []
    while queue:
        cx, cy = queue.popleft()
        component.append((cx, cy))
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 'X' and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny))
    return component

def is_valid_partition(grid, h, w, components, k):
    if len(components) % k != 0:
        return False
    component_size = len(components) // k
    for i in range(k):
        for j in range(component_size):
            if components[i * component_size + j] != components[(i + 1) * component_size + j]:
                return False
    return True

def solve(h, w, grid):
    visited = [[False] * w for _ in range(h)]
    components = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 'X' and not visited[i][j]:
                component = bfs(grid, h, w, i, j, visited)
                components.append(sorted(component))

    components.sort(key=lambda x: len(x))

    for k in range(2, 6):
        if is_valid_partition(grid, h, w, components, k):
            result_grid = [['.' for _ in range(w)] for _ in range(h)]
            component_size = len(components) // k
